try {
  let income = null;
  let expenses = null;

  if (query && typeof query === 'object') {
    income = typeof query.monthly_income === 'number' ? query.monthly_income : (parseFloat(query.monthly_income) || null);
    expenses = typeof query.monthly_expenses === 'number' ? query.monthly_expenses : (parseFloat(query.monthly_expenses) || null);
  }

  if (income === null || expenses === null) {
    let text = '';
    if (typeof query === 'string') {
      text = query;
    } else if (query && typeof query === 'object') {
      text = query.query || query.input || '';
    }

    const parseNum = (matchResult) => {
      if (!matchResult) return null;
      let val = parseFloat(matchResult[1]);
      const unit = (matchResult[2] || '').toLowerCase();
      if (unit.startsWith('k')) val *= 1000;
      else if (unit.startsWith('l')) val *= 100000;
      else if (unit.startsWith('m')) val *= 1000000;
      return val;
    };

    if (income === null) {
      income = parseNum(text.match(/(?:income|earn|salary|inflow)\D*(\d+(?:\.\d+)?)\s*(k|lakh|l|m)?/i));
    }
    if (expenses === null) {
      expenses = parseNum(text.match(/(?:expense|spend|outgo|cost|bill)\D*(\d+(?:\.\d+)?)\s*(k|lakh|l|m)?/i));
    }

    if (income === null || expenses === null) {
      const numbers = [];
      const numRegex = /(\d+(?:\.\d+)?)\s*(k|lakh|l|m)?/gi;
      let m;
      while ((m = numRegex.exec(text)) !== null) {
        let val = parseFloat(m[1]);
        const unit = (m[2] || '').toLowerCase();
        if (unit.startsWith('k')) val *= 1000;
        else if (unit.startsWith('l')) val *= 100000;
        else if (unit.startsWith('m')) val *= 1000000;
        numbers.push(val);
      }
      if (numbers.length >= 2) {
        if (income === null && expenses === null) {
          income = Math.max(numbers[0], numbers[1]);
          expenses = Math.min(numbers[0], numbers[1]);
        } else if (income === null) {
          income = numbers.find(n => n !== expenses) || expenses * 1.5;
        } else if (expenses === null) {
          expenses = numbers.find(n => n !== income) || income * 0.6;
        }
      }
    }
  }

  if (income === null || expenses === null) {
    const missing = [];
    if (income === null) missing.push('monthly_income');
    if (expenses === null) missing.push('monthly_expenses');
    return `Error: Missing required inputs for Budget calculation. Required: ${missing.join(', ')}.`;
  }

  if (income <= 0) return 'Error: Income must be greater than zero.';

  const surplus = income - expenses;
  const savings_rate = (surplus / income) * 100;
  const needs_50 = income * 0.50;
  const wants_30 = income * 0.30;
  const savings_20 = income * 0.20;
  const emergency_fund = expenses * 6;

  const fmt = (num) => num.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });

  return `Monthly Income: INR ${fmt(income)}
Monthly Expenses: INR ${fmt(expenses)}
Monthly Surplus: INR ${fmt(surplus)}
Savings Rate: ${savings_rate.toFixed(2)}%
50-30-20 Allocation Plan:
- Needs (50%): INR ${fmt(needs_50)}
- Wants (30%): INR ${fmt(wants_30)}
- Savings (20%): INR ${fmt(savings_20)}
6-Month Emergency Fund Target: INR ${fmt(emergency_fund)}`;
} catch (e) {
  return 'Error: ' + e.message;
}

try {
  let sip = null;
  let rate_annual = null;
  let years = null;

  if (query && typeof query === 'object') {
    sip = typeof query.monthly_investment === 'number' ? query.monthly_investment : (parseFloat(query.monthly_investment) || null);
    rate_annual = typeof query.expected_return_rate === 'number' ? query.expected_return_rate : (parseFloat(query.expected_return_rate) || null);
    years = typeof query.years === 'number' ? query.years : (parseInt(query.years) || null);
  }

  if (sip === null || rate_annual === null || years === null) {
    let text = '';
    if (typeof query === 'string') {
      text = query;
    } else if (query && typeof query === 'object') {
      text = query.query || query.input || '';
    }

    const parseNum = (matchResult) => {
      if (!matchResult) return null;
      let val = parseFloat(matchResult[1]);
      const unit = (matchResult[2] || '').toLowerCase();
      if (unit.startsWith('k')) val *= 1000;
      else if (unit.startsWith('l')) val *= 100000;
      else if (unit.startsWith('m')) val *= 1000000;
      return val;
    };

    if (sip === null) {
      sip = parseNum(text.match(/(?:sip|monthly|invest|saving)\D*(\d+(?:\.\d+)?)\s*(k|lakh|l|m)?/i));
    }
    if (rate_annual === null) {
      const pctMatch = text.match(/(\d+(?:\.\d+)?)\s*%/);
      if (pctMatch) {
        rate_annual = parseFloat(pctMatch[1]);
      } else {
        const rateMatch = text.match(/(?:rate|return|interest|yield)\D*(\d+(?:\.\d+)?)/i);
        if (rateMatch) rate_annual = parseFloat(rateMatch[1]);
      }
    }
    if (years === null) {
      const yrMatch = text.match(/(\d+)\s*(?:year|yr|y)/i);
      if (yrMatch) {
        years = parseInt(yrMatch[1]);
      } else {
        const yearsMatch = text.match(/(?:year|duration|time|period)\D*(\d+)/i);
        if (yearsMatch) years = parseInt(yearsMatch[1]);
      }
    }
  }

  if (sip === null || rate_annual === null || years === null) {
    const missing = [];
    if (sip === null) missing.push('monthly_investment');
    if (rate_annual === null) missing.push('expected_return_rate');
    if (years === null) missing.push('years');
    return `Error: Missing required inputs for SIP calculation. Required: ${missing.join(', ')}.`;
  }

  const rate_monthly = rate_annual / 12 / 100;
  const months = years * 12;
  const total_invested = sip * months;
  const maturity_value = sip * ((Math.pow(1 + rate_monthly, months) - 1) / rate_monthly) * (1 + rate_monthly);
  const estimated_returns = maturity_value - total_invested;

  const fmt = (num) => num.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });

  return `Monthly SIP: INR ${fmt(sip)}
Tenure: ${years} years (${months} months)
Expected Return Rate: ${rate_annual.toFixed(2)}%
Total Invested: INR ${fmt(total_invested)}
Maturity Value: INR ${fmt(maturity_value)}
Wealth Gained: INR ${fmt(estimated_returns)}`;
} catch (e) {
  return 'Error: ' + e.message;
}

try {
  let principal = null;
  let rate_annual = null;
  let years = null;

  if (query && typeof query === 'object') {
    principal = typeof query.principal === 'number' ? query.principal : (parseFloat(query.principal) || null);
    rate_annual = typeof query.annual_interest_rate === 'number' ? query.annual_interest_rate : (parseFloat(query.annual_interest_rate) || null);
    years = typeof query.years === 'number' ? query.years : (parseInt(query.years) || null);
  }

  if (principal === null || rate_annual === null || years === null) {
    let text = '';
    if (typeof query === 'string') {
      text = query;
    } else if (query && typeof query === 'object') {
      text = query.query || query.input || '';
    }

    const parseNum = (matchResult) => {
      if (!matchResult) return null;
      let val = parseFloat(matchResult[1]);
      const unit = (matchResult[2] || '').toLowerCase();
      if (unit.startsWith('k')) val *= 1000;
      else if (unit.startsWith('l')) val *= 100000;
      else if (unit.startsWith('m')) val *= 1000000;
      return val;
    };

    if (principal === null) {
      principal = parseNum(text.match(/(?:principal|loan|debt|amount)\D*(\d+(?:\.\d+)?)\s*(k|lakh|l|m)?/i));
    }
    if (rate_annual === null) {
      const pctMatch = text.match(/(\d+(?:\.\d+)?)\s*%/);
      if (pctMatch) {
        rate_annual = parseFloat(pctMatch[1]);
      } else {
        const rateMatch = text.match(/(?:rate|interest)\D*(\d+(?:\.\d+)?)/i);
        if (rateMatch) rate_annual = parseFloat(rateMatch[1]);
      }
    }
    if (years === null) {
      const yrMatch = text.match(/(\d+)\s*(?:year|yr|y)/i);
      if (yrMatch) {
        years = parseInt(yrMatch[1]);
      } else {
        const yearsMatch = text.match(/(?:year|duration|time|period|tenure)\D*(\d+)/i);
        if (yearsMatch) years = parseInt(yearsMatch[1]);
      }
    }
  }

  if (principal === null || rate_annual === null || years === null) {
    const missing = [];
    if (principal === null) missing.push('principal');
    if (rate_annual === null) missing.push('annual_interest_rate');
    if (years === null) missing.push('years');
    return `Error: Missing required inputs for EMI calculation. Required: ${missing.join(', ')}.`;
  }

  const rate_monthly = rate_annual / 12 / 100;
  const months = years * 12;
  const emi = principal * rate_monthly * Math.pow(1 + rate_monthly, months) / (Math.pow(1 + rate_monthly, months) - 1);
  const total_payment = emi * months;
  const total_interest = total_payment - principal;

  const fmt = (num) => num.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });

  return `Loan Principal: INR ${fmt(principal)}
Tenure: ${years} years (${months} months)
Annual Interest Rate: ${rate_annual.toFixed(2)}%
Monthly EMI: INR ${fmt(emi)}
Total Payment: INR ${fmt(total_payment)}
Total Interest Payable: INR ${fmt(total_interest)}`;
} catch (e) {
  return 'Error: ' + e.message;
}

try {
  let income = null;

  if (query && typeof query === 'object') {
    income = typeof query.annual_income === 'number' ? query.annual_income : (parseFloat(query.annual_income) || null);
  }

  if (income === null) {
    let text = '';
    if (typeof query === 'string') {
      text = query;
    } else if (query && typeof query === 'object') {
      text = query.query || query.input || '';
    }

    const parseNum = (matchResult) => {
      if (!matchResult) return null;
      let val = parseFloat(matchResult[1]);
      const unit = (matchResult[2] || '').toLowerCase();
      if (unit.startsWith('k')) val *= 1000;
      else if (unit.startsWith('l')) val *= 100000;
      else if (unit.startsWith('m')) val *= 1000000;
      return val;
    };

    income = parseNum(text.match(/(?:income|earn|salary|annual|taxable)\D*(\d+(?:\.\d+)?)\s*(k|lakh|l|m)?/i));
    if (income === null) {
      const numbers = [];
      const numRegex = /(\d+(?:\.\d+)?)\s*(k|lakh|l|m)?/gi;
      let m;
      while ((m = numRegex.exec(text)) !== null) {
        let val = parseFloat(m[1]);
        const unit = (m[2] || '').toLowerCase();
        if (unit.startsWith('k')) val *= 1000;
        else if (unit.startsWith('l')) val *= 100000;
        else if (unit.startsWith('m')) val *= 1000000;
        numbers.push(val);
      }
      income = numbers.find(n => n > 1000) || null;
    }
  }

  if (income === null) {
    return 'Error: Missing required inputs for Tax calculation. Required: annual_income.';
  }

  if (income > 0 && income < 100000) {
    income = income * 12;
  }

  const net_new = Math.max(0, income - 75000);
  let tax_new = 0;
  if (net_new > 700000) {
    let temp = net_new;
    if (temp > 1500000) { tax_new += (temp - 1500000) * 0.3; temp = 1500000; }
    if (temp > 1200000) { tax_new += (temp - 1200000) * 0.2; temp = 1200000; }
    if (temp > 900000)  { tax_new += (temp - 900000) * 0.15; temp = 900000; }
    if (temp > 600000)  { tax_new += (temp - 600000) * 0.1; temp = 600000; }
    if (temp > 300000)  { tax_new += (temp - 300000) * 0.05; temp = 300000; }
  }

  const deductions_old = 50000 + 150000 + 25000;
  const net_old = Math.max(0, income - deductions_old);
  let tax_old = 0;
  if (net_old > 500000) {
    let temp = net_old;
    if (temp > 1000000) { tax_old += (temp - 1000000) * 0.3; temp = 1000000; }
    if (temp > 500000)  { tax_old += (temp - 500000) * 0.2; temp = 500000; }
    if (temp > 250000)  { tax_old += (temp - 250000) * 0.05; temp = 250000; }
  }

  const fmt = (num) => num.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });

  return `Annual Taxable Income: INR ${fmt(income)}
Tax New Regime: INR ${fmt(tax_new)}
Tax Old Regime: INR ${fmt(tax_old)}`;
} catch (e) {
  return 'Error: ' + e.message;
}

